// Sequential circuit, the output state of the flip-flop has been
// observable through the output port. The combinational logic is
// triggered on the positive edge of the clock.
module TopModule (
    input  clk,
    input  a,
    input  b,
    output q,
    output state
);
    reg state_reg;
    wire q_next;
    assign q_next = a ^ b ^ state_reg;
    always @(posedge clk) state_reg <= q_next;
    assign state = state_reg;
    assign q = ~state_reg;
endmodule

